from save_review import save
save(1220,{2:'许多霰弹枪能够使用多种弹药，包括非致命的塑料棍弹、独头弹、装填小弹丸的霰弹，以及更特殊的型号。',5:'VXII 自动制导瞄准弹药深受基列主星贵族执法力量青睐。它先与霰弹枪的瞄准系统配对，再依靠弹内智能制导装置，精准追踪并命中目标。对付躲入拥挤人群或密集城区的重要罪犯时，这类弹药尤其有效。它从远处发射后，需要短暂时间完成目标生物锁定，随后紧追不舍，最终爆炸。由于结构复杂，必须配合多数人无法取得的先进瞄准设备使用。',8:'标准霰弹枪弹药之一，将许多小弹丸散射到较大区域。',9:'Avachrun Forgeshot 阿瓦赫鲁斯铸击弹',11:'这类弹药产自阿瓦赫鲁斯。当地在工业开采星核时产生富含矿物的粉尘，将其回收、压实后，再用于制造著名铸击弹的弹壳。其金属材料密度达到普通钢材的数倍，射出的弹丸能在近距离轻易贯穿装甲或舱壁。',14:'生物冲击者 X76 由驻内特里乌斯的机械修会人员专门为杀伤有机目标设计，内含从当地巨型动物提取的致命突触抑制毒素。它以微小玻璃珠替代标准陶钢弹丸，开火时玻璃珠碎裂，释放毒素，形成一片带毒碎片雨。命中后，毒素会在细胞层面侵害目标；即使最初的冲击未能解除威胁，毒素也会在数秒内使其失去行动能力，任人处置。',17:'墓穴清除者弹药触及目标便会炸裂，把致命破片撒向爆炸区域。它适合对付试图凭借密集数量或高速行动占优的异形；破片会在封闭空间内迅速扩散，轻易扫倒敌人。',20:'行刑者弹药最常由法务部人员使用，内置微型制导装置，可自行追踪目标。不过，它需要片刻才能完成锁定，因此距离较远时反而更准确。',23:'铁磁弹药源自因维特，由帝国之拳军团使用。这种重型霰弹枪弹药不散射破片，而是射出一枚带电弹头；命中陶钢等特殊材料后，弹头先附着其上，再行爆炸，在与敌方阿斯塔特军团战士的近距离交火中十分致命。',29:'最早进入基列星系的探索者曾广泛使用照明信号弹，如今这种弹药已很罕见，也常被忽视。它以标准枪弹为基础，专为照明或遇险时提供引导信标而设计。因弹体和点火系统较大，只能由大口径霰弹手枪发射。弹内的小型燃料电池推进系统使其升入高空；若在近距离或封闭空间内发射，却可能引发毁灭性爆炸，连强化装甲舰体也能炸穿。伴随的强光还可能损伤视力并引发额外燃烧，因此这种用法极不明智。',35:'内特雷恩穿透弹药由内特雷乌斯军务人员使用，是带有爆炸推进装药与定时热压部件的大口径实体弹药。它能先穿透当地野兽的厚皮或鳞片，再于数毫秒后在目标体内猛烈爆炸。',38:'龙息弹药最常由死亡守望星际战士使用，能够喷出波浪般的圣化火焰，适合对付成群叫嚣的罪犯或异形。烈焰可迅速吞没整个房间或拥挤走廊，对防护薄弱的目标效果尤佳：最初的冲击先撕裂血肉，随后将其点燃。',41:'死亡守望武库中的异形净化弹药发射重型独头弹，专门贯穿多种异形的天然护甲、撕裂要害器官，因而常用于对付泰伦虫族及其他偏好虫群战术的昆虫型种族。如同死亡守望的许多装备，其确切结构只有经严格审查、获特别选任且立誓保密的技术祭司知晓。'},
{5:'底稿apprehending与后述爆炸杀伤并列，保留执法背景而不将其擅定为非致命捕获弹。',11:'源文先说矿物用于制造弹壳，随后转而谈弹丸密度与穿透力，表述不够明确；按原叙述保留，不补造弹芯工艺。',12:'标题N-MF-76与正文X76型号不同，英文与中文分别保留，标待核，不能擅自统一编号。',14:'本段Nethrius、下文Nethreus拼写有异；中文暂分别转写，待原资料核对。',29:'英文重复ventured into the Gilead System，中文去除重复；Shotgun Pistol为霰弹手枪，不是泛称大口径霰弹枪。',38:'xenos是异形，原译异教徒错误。'},
[('Pellet-Filled Cannister Round','霰弹'),('VXII Auto-GuideSys Targeting Shell','VXII 自动制导瞄准弹药'),('Scatter (shotgun ammunition)','散射弹药'),('Avachrun Forgeshot','阿瓦赫鲁斯铸击弹'),('Biologis Impacter N-MF-76','生物冲击者 N-MF-76'),('Biologis Impacter X76','生物冲击者 X76'),('Cryptclearer','墓穴清除者'),('Executioner rounds','行刑者弹药'),('Ferromag','铁磁弹药'),('Illuminator Flare Round','照明信号弹'),('Nethreun Penetrator','内特雷恩穿透弹药'),('Wyrmsbreath','龙息弹药'),('Xenopurge','异形净化弹药')])
save(1221,{2:'榴弹发射器是结构相对简单的管状武器，利用压缩气体、电磁力等方式发射多种榴弹。它能让弹药沿弧线飞行，越过障碍，压制视线之外的敌人。尽管兼容多种常见榴弹，实际最常装填的是破片与穿甲榴弹。其他弹种包括反植物、致盲、致幻、等离子、烟雾、眩晕、病毒和异丝榴弹。',6:'榴弹发射器的射程与精度都优于手投，因此是帝国卫队步兵班的常见武器，主要负责火力压制，以及摧毁轻型载具和建筑。其他种族同样使用它：灵族翔鹰支派战士将发射器绑在腿部，丑角暗影先知则使用肩部安装的型号；钛族脉冲卡宾枪也下挂榴弹发射器，用来发射电磁脉冲榴弹。',10:'Cadian pattern grenade launcher 卡迪亚型榴弹发射器',12:'卡迪亚型是卡迪亚突击军的标准榴弹发射器，采用弹鼓供弹，容量二十发，口径40毫米，射速较高，装填时需将武器前部转开。前方准星和可翻起的后照门辅助瞄准，后者设有不同射程的标记。射击时需要双腿分开、稳固站立，因为后坐力堪比爆矢枪，操作不当容易受伤。',16:'An Armageddon Steel Legion member with a Grenade Launcher 装备榴弹发射器的阿玛吉多顿钢铁军团士兵',20:'Vostroyan Firstborn with a Grenade Launcher 装备榴弹发射器的沃斯特洛亚长子团士兵',23:'一种便于深度改装的榴弹发射器型号，深受涅克罗蒙达帮派成员和雇佣枪手欢迎。',28:'峡谷型是一款结构简单的单发折开式榴弹发射器。简单的设计并未削弱其效能；它紧凑可靠，是执法者、雇佣兵与行星防卫军最常使用的班组支援武器之一。黑市上也很容易取得，因此不法分子和叛乱组织常用它发动袭击与暴动。',31:'这种武器产自梅佐亚铸造世界。虽然是单发型号，但射程、精度和击发系统都优于当地其他常见武器，因此在克洛诺斯广域备受推崇。',32:'SLHG Pattern Assault Ram SLHG 型突击破门锤',34:'执法者使用的突击破门锤，下挂辅助榴弹发射器。',42:'沃斯型自动榴弹发射器采用六发转轮弹仓，但精度不足，使许多人望而却步。Mk.V 改型以高射速弥补这一缺点，几乎能跟随射手每次扣动扳机发射榴弹，用密集火力覆盖目标。空降团等精锐部队常以此弥补人数不足，艾丽西亚空降部队就是其使用者。',50:'死亡守卫守墓人使用的专属榴弹发射器。歌利亚家族帮派中也出现过较小的手持版本，通常成对使用。',56:'House Goliath ganger with paired Assault Grenade Launchers 装备一对突击榴弹发射器的歌利亚家族帮派成员',59:'星际战士侦察摩托可装配这种榴弹发射器，其自适应瞄准装置能补偿高速移动带来的影响。有时它也安装在终结者装甲上。',63:'Space Marine Scout Bike with an Astartes Grenade Launcher 装备阿斯塔特榴弹发射器的星际战士侦察摩托',66:'安装在载具或固定阵地上、用于扰乱敌方步兵的榴弹发射器。',76:'Blight Launcher 枯萎发射器',78:'死亡守卫腐毒领主终结者和瘟疫战士使用的重型榴弹发射器。',81:'单发一次性榴弹发射器，操作简便，受到行星防卫军欢迎。',84:'原铸星际战士侵略者小队和救赎者无畏机甲使用的榴弹发射器。',87:'大远征和荷鲁斯之乱期间，圣血天使破晓者大队使用的腕部榴弹发射器。',88:'Grenade Harness 背带式榴弹发射器',90:'大远征和荷鲁斯之乱期间，安装在终结者装甲上的榴弹发射器。',96:'安装在原铸百夫长和铁甲无畏机甲胸部的榴弹发射器。',99:'原铸星际战士反重力战车使用的榴弹发射器。',103:'Stormfrag Auto-Launcher 风暴破片自动发射器',111:'格莱亚机械修会研制的实验性星际战士榴弹发射器。',112:'Vratine Grenade Launcher 弗拉廷榴弹发射器',119:'Terminator Captain with Wrist-Mounted Grenade Launcher 装备腕戴式榴弹发射器的终结者连长',132:'发射带刺榴弹的武器，弹药能够释放引发恐惧的气体。',141:'Cthonian Beserk Mole Grenade Launcher 深岩狂战士鼹鼠榴弹发射器',143:'沃坦联盟根据鼹鼠发射器衍生出的武器。',147:'Orks 欧克',152:'Pulse Submunitions Rifle 脉冲子母弹步枪',154:'危险型近距离支援战斗服使用的钛族武器，功能相当于榴弹发射器。'},
{2:'clear obstacles指越过障碍，不是清除障碍；electromagnetic charge按发射机制理解为电磁力，不是电磁装药。',12:'boltgun是爆矢枪，原译霰弹枪错误。',32:'Assault Ram在这里是执法者手持破门装备，不是突击艇；若其他条目为Caestus Assault Ram载具，须分义。',36:'英文ingle-hand缺首字母S，按single-hand理解单手，保留原文。',96:'底稿写Primaris Centurions，身份分类可能有疑，忠实保留并标记，不擅删Primaris。',103:'Stormfrag中的frag是破片，不是獠牙。',141:'Cthonian Beserks在GW09与GW10第27页对应深岩狂战士，武器全名据单位词根暂译，未作完整官译认证。'},
[('Grenade launcher','榴弹发射器'),('Cadian pattern grenade launcher','卡迪亚型榴弹发射器'),('Funeral Ball','葬礼之球'),('Gorge Pattern Grenade Launcher','峡谷型榴弹发射器'),('Mezoa Grenade Launcher','梅佐亚榴弹发射器'),('SLHG Pattern Assault Ram','SLHG 型突击破门锤'),('Subjugator Pattern Grenade Launcher','压制者型榴弹发射器'),('Voss Pattern Grenade Launcher','沃斯型榴弹发射器'),('Assault Grenade Launcher','突击榴弹发射器'),('Astartes Grenade Launcher','阿斯塔特榴弹发射器'),('Auto-Launcher','自动发射器'),('Auxiliary Grenade Launcher','辅助榴弹发射器'),('Balistus Grenade Launcher','巴利斯图斯榴弹发射器'),('Blackstar Cluster Launcher','黑星集群发射器'),('Disposable Grenade Launcher','一次性榴弹发射器'),('Fragstorm Grenade Launcher','破片风暴榴弹发射器'),('Grenade Discharger','掷弹筒'),('Grenade Harness','背带式榴弹发射器'),('Grenadier Gauntlet','掷弹臂铠'),('Ironclad Assault Launcher','铁甲突击发射器'),('Krakstorm Grenade Launcher','破甲风暴榴弹发射器'),('Ravenwing Grenade Launcher','鸦翼榴弹发射器'),('Stormfrag Auto-Launcher','风暴破片自动发射器'),('Tauros Grenade Launcher','金牛座榴弹发射器'),('Vratine Grenade Launcher','弗拉廷榴弹发射器'),('Phantasm Grenade Launcher','幻影榴弹发射器'),('Horrorfex','恐惧榴弹发射器'),('Terrorfex','恐怖榴弹发射器'),('Torment Grenade Launcher','折磨榴弹发射器'),('Pack Grenade Launcher','背包榴弹发射器'),('Swooping Hawk grenade pack','翔鹰榴弹背包'),('Cthonian Beserk Mole Grenade Launcher','深岩狂战士鼹鼠榴弹发射器'),('Exo-Armour Grenade Launcher','外骨骼装甲榴弹发射器'),('Stikkbomb Chukka','棍子炸弹发射器'),('Pulse Submunitions Rifle','脉冲子母弹步枪')])
save(1222,{2:'辅助榴弹发射器是榴弹发射器的缩小型号，可安装在爆矢枪、激光枪和自动枪等帝国武器上，使使用者能够发射预先装填、完成击发准备的榴弹。手枪尺寸太小，无法搭载这种附件。',6:'拨动切换卡笋后，主武器的击发机构会停用，辅助发射器则被启用。此时扣动扳机，便会向敌人发射一枚榴弹。',8:'许多辅助发射器有独立弹匣，能够容纳多枚榴弹，但一次只装填同一种弹药。最常见的是穿甲榴弹，可补充近距离火力与反载具能力；破片榴弹和其他常见弹种也能使用。另一些型号只能装填一发，虽然兼容多种弹种，但笨重且不便操作，多数使用者打空后便很少再装填。'}, {6:'throwing a catch指拨动卡笋，不是撞击锁闩。'})
save(1223,{2:'复仇榴弹发射器是格莱亚铸造世界的机械修会研制的一种实验性武器，诞生于欧克战争头目恐颅入侵前夕。它尚未获准在星球之外使用，但参加实战测试的星际战士证实，它能有效对付多类目标。发射器最多可射出五枚能够黏附表面的爆炸装药，再以遥控方式引爆。'}, {2:'off world指星球之外，原“世界各地”改变了使用限制范围。'},[('Vengeance Grenade Launcher','复仇榴弹发射器'),('Grimskull (Ork Warboss)','恐颅')])
save(1224,{2:'腕戴式榴弹发射器是星际战士使用的一种武器，已知可安装在连长的终结者装甲上。',7:'热能复合拳——内置动力拳的复合武器，可在较远距离发射热能炸弹，对付装甲目标和步兵。',9:'巴利斯图斯榴弹发射器——禁军使用的榴弹发射器，擅长穿甲。',11:'掷弹筒——大远征和荷鲁斯之乱期间，圣血天使破晓者大队使用的武器。',13:'恐怖榴弹发射器——黑暗灵族步兵使用的武器。'},terms=[('Wrist-Mounted Grenade Launcher','腕戴式榴弹发射器'),('Thermogenic Combi-Fist','热能复合拳')],title='腕戴式榴弹发射器 Wrist-Mounted Grenade Launcher')
save(1225,{2:'背带式榴弹发射器安装在部分星际战士终结者装甲上，通常在终结者发起冲锋前，向敌人倾泻一轮破片榴弹。'},terms=[('Grenade Harness Launcher','背带式榴弹发射器')])
